    name: 'Nest Egg',
    icon: 'coin',
    desc: 'Finish with at least $2,000 in cash.',
    check: (_state, player) => player.cash >= 2000,
  },
];

export const GOAL_BY_ID = Object.fromEntries(GOALS.map((goal) => [goal.id, goal]));

export function countAssets(state, playerId, filter = () => true) {
  return Object.entries(state.owners).filter(([tileId, own]) => {
    return own.owner === playerId && filter(TILE_BY_ID[Number(tileId)]);
  }).length;
}

export function hasMaxLevelAsset(state, playerId) {
  return Object.values(state.owners).some((own) => own.owner === playerId && own.level >= 3);
}

export function ownsGroup(state, playerId, district) {
  const ids = GROUP_TILES[district] || [];
  return ids.length > 0 && ids.every((id) => state.owners[id]?.owner === playerId);
}

export function rentFor(state, tileId) {
  const tile = TILE_BY_ID[tileId];
  const own = state.owners[tileId];
  if (!tile || !own) return 0;
  const base = tile.rent[own.level - 1] || tile.rent[0];
  return ownsGroup(state, own.owner, tile.district) ? base * CONFIG.groupRentMultiplier : base;
}

export function upgradeCost(tile, level) {
  return Math.round((tile.price * CONFIG.upgradeCosts[level - 1]) / 10) * 10;
}

export function assetValue(tile, level) {
  return Math.round(tile.price * [0, 0.7, 0.85, 1][level]);
}

export const RULES = [
  {
    icon: 'star',
    title: 'Build a life',
    text: 'Travel the board through Childhood, Career, Family and Adventure. Pass Fresh Start to collect your salary and begin a new chapter.',
  },
  {
    icon: 'home',
    title: 'Own your story',
    text: 'Land on an unowned property to buy it. Land on your own property to upgrade it. Land on someone else’s to pay rent — owning a full colour group doubles it.',
  },
  {
    icon: 'compass',
    title: 'Make choices',
    text: 'Milestones like Graduation, Wedding and Midlife ask you to choose. There is no single right answer — every path has a price and a payoff.',
  },
  {
    icon: 'heart',
    title: 'Win at life',
    text: 'After the final chapter, your score combines cash, assets, happiness, family, your secret life goal and retirement. Money alone rarely wins.',
  },
];

// Small, fast, serialisable PRNG. The whole game state carries its own seed so
// saves are reproducible and tests can be deterministic.
export function nextRandom(state) {
  state.rng = (state.rng + 0x6d2b79f5) >>> 0;
  let t = state.rng;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}

export function randomInt(state, min, max) {
  return min + Math.floor(nextRandom(state) * (max - min + 1));
}

export function shuffle(state, items) {
  const copy = [...items];
  for (let i = copy.length - 1; i > 0; i--) {
    const j = Math.floor(nextRandom(state) * (i + 1));
    [copy[i], copy[j]] = [copy[j], copy[i]];
  }
  return copy;
}

export function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

import {
  CARDS,
  CHOICES,
  CONFIG,
  GOALS,
  GOAL_BY_ID,
  TILES,
  TILE_BY_ID,
  assetValue,
  countAssets,
  hasMaxLevelAsset,
  rentFor,
  upgradeCost,
} from './data.js';
import { clamp, nextRandom, randomInt, shuffle } from './rng.js';

const TILE_COUNT = TILES.length;
const CARD_BY_ID = Object.fromEntries(CARDS.map((card) => [card.id, card]));

export function currentPlayer(state) {
  return state.players[state.current];
}

export function createGame({ players, laps = CONFIG.laps, seed = Math.floor(Math.random() * 1e9) } = {}) {
  const safePlayers = (players && players.length ? players : [{ name: 'You', isAI: false }]).slice(0, 4);
  const state = {
    version: 1,
    seed,
    rng: seed >>> 0,
    laps: Math.max(1, Math.min(5, laps)),
    players: safePlayers.map((player, index) => ({
      id: index,
      name: player.name || `Player ${index + 1}`,
      color: player.color,
      isAI: Boolean(player.isAI),
      cash: CONFIG.startingCash,
      salary: CONFIG.baseSalary,
      happiness: CONFIG.startingHappiness,
      position: 0,
      laps: 0,
      partner: false,
      kids: 0,
      retired: false,
      bankrupt: false,
      goal: null,
      flags: {},
      stats: { assetsBought: 0, rentPaid: 0, rentEarned: 0, events: 0, donated: 0 },
    })),
    owners: {},
    deck: [],
    deckIndex: 0,
    current: 0,
    phase: 'roll',
    turn: 1,
    lastRoll: null,
    pending: null,
    log: [],
    winner: null,
    results: null,
    startedAt: Date.now(),
  };

  const goals = shuffle(state, GOALS.map((goal) => goal.id));
  state.players.forEach((player, index) => {
    player.goal = goals[index % goals.length];
  });
  state.deck = shuffle(state, CARDS.map((card) => card.id));

  addLog(state, `${state.players[0].name} begins a brand new life.`, 'start');
  addLog(state, 'Roll the die to take your first steps.', 'info');
  return state;
}

// ---------------------------------------------------------------------------
// Turn flow
// ---------------------------------------------------------------------------

export function rollDice(state) {
  if (state.phase !== 'roll') throw new Error(`Cannot roll during phase ${state.phase}`);
  const player = currentPlayer(state);
  if (player.retired || player.bankrupt) throw new Error('Player is not active');

  const roll = randomInt(state, 1, 6);
  const from = player.position;
  const path = [];
  for (let step = 1; step <= roll; step++) path.push((from + step) % TILE_COUNT);

  state.lastRoll = roll;
  state.phase = 'moving';
  return { roll, from, path, to: path[path.length - 1] };
}

export function completeMove(state) {
  if (state.phase !== 'moving') throw new Error(`Cannot complete move during phase ${state.phase}`);
  const player = currentPlayer(state);
  const events = [];
  const from = player.position;
  const roll = state.lastRoll;
  const to = (from + roll) % TILE_COUNT;
  const passedStart = from + roll >= TILE_COUNT;

  player.position = to;

  if (passedStart) {
    player.laps += 1;
    player.cash += player.salary;
    events.push({ type: 'salary', playerId: player.id, amount: player.salary });
    addLog(state, `${player.name} passes Fresh Start and collects $${player.salary} salary.`, 'money');
    addLog(state, `Chapter ${Math.min(player.laps + 1, state.laps)} begins.`, 'info');
  }

  const landing = resolveLanding(state, player, to, events);
  if (landing) events.push(landing);
  if (state.pending) state.phase = 'action';
  else if (player.bankrupt) state.phase = 'end';
  else state.phase = 'end';

  return { events, from, to, passedStart, roll };
}

function resolveLanding(state, player, tileId, events) {
  const tile = TILE_BY_ID[tileId];
  events.push({ type: 'land', playerId: player.id, tileId });

  switch (tile.type) {
    case 'property': {
      const owned = state.owners[tileId];
      if (!owned) {
        state.pending = { type: 'buy', tileId, playerId: player.id };
        events.push({ type: 'offer', kind: 'buy', tileId });
        addLog(state, `${player.name} arrives at ${tile.name}. It is for sale for $${tile.price}.`, 'info');
        return null;
      }
      if (owned.owner === player.id) {
        if (owned.level < 3) {
          const cost = upgradeCost(tile, owned.level);
          state.pending = { type: 'upgrade', tileId, cost, playerId: player.id };
          events.push({ type: 'offer', kind: 'upgrade', tileId, cost });
          addLog(state, `${player.name} visits their own ${tile.name}. Upgrade available for $${cost}.`, 'info');
        } else {
          applyHappiness(state, player, 2, events);
          addLog(state, `${player.name} enjoys their fully upgraded ${tile.name}. +2 happiness.`, 'happy');
        }
        return null;
      }

      const owner = state.players[owned.owner];
      const rent = rentFor(state, tileId);
      const paid = payPlayer(state, player, owner, rent, `rent at ${tile.name}`);
      player.stats.rentPaid += paid;
      owner.stats.rentEarned += paid;
      addLog(
        state,
        `${player.name} pays $${paid} rent to ${owner.name} at ${tile.name}${rent > tile.rent[owned.level - 1] ? ' (full group bonus!)' : ''}.`,
        'money',
      );
      events.push({ type: 'rent', fromId: player.id, toId: owner.id, amount: paid, tileId });
      if (player.bankrupt) events.push({ type: 'bankrupt', playerId: player.id });
      return null;
    }

    case 'event': {
      const card = drawCard(state, player, events);
      return card;
    }

    case 'bonus': {
      if (tile.cash) applyCash(state, player, tile.cash, events);
      if (tile.salary) {
        player.salary = Math.max(100, player.salary + tile.salary);
        events.push({ type: 'salaryUp', playerId: player.id, amount: tile.salary });
      }
      if (tile.happiness) applyHappiness(state, player, tile.happiness, events);
      addLog(state, `${tile.name}: +$${tile.cash || 0}${tile.salary ? `, salary +$${tile.salary}` : ''}${tile.happiness ? `, +${tile.happiness} happiness` : ''}.`, 'good');
      return null;
    }

    case 'rest': {
      applyHappiness(state, player, tile.happiness || 4, events);
      addLog(state, `${player.name} takes a moment at the ${tile.name}. +${tile.happiness || 4} happiness.`, 'happy');
      return null;
    }

    case 'start': {
      applyCash(state, player, 100, events);
      applyHappiness(state, player, 3, events);
      addLog(state, `${player.name} lands on Fresh Start. A little bonus for new beginnings: +$100.`, 'good');
      return null;
    }

    case 'emptyNest': {
      if (player.kids > 0) {
        const bonus = 120 * player.kids;
        applyCash(state, player, bonus, events);
        applyHappiness(state, player, 8, events);
        addLog(state, `${player.name} watches the kids fly the nest. +$${bonus}, +8 happiness.`, 'happy');
      } else {
        applyCash(state, player, 80, events);
        applyHappiness(state, player, 4, events);
        addLog(state, `${player.name} enjoys a quiet, wonderfully cheap house. +$80.`, 'good');
      }
      return null;
    }

    case 'choice': {
      const choice = choiceFor(state, tile.choiceId, player);
      state.pending = { type: 'choice', choiceId: choice.id, tileId, playerId: player.id };
      events.push({ type: 'choice', choiceId: choice.id, tileId });
      addLog(state, `${player.name} faces a milestone: ${choice.title}.`, 'choice');
      return null;
    }

    default:
      return null;
  }
}

// ---------------------------------------------------------------------------
// Pending decisions
// ---------------------------------------------------------------------------

export function choiceFor(state, choiceId, player) {
  const base = CHOICES[choiceId];
  if (!base) throw new Error(`Unknown choice ${choiceId}`);

  if (choiceId === 'wedding' && player.partner) {
    return {
      ...base,
      title: 'Anniversary',
      prompt: 'A familiar face, a shared history, and one more year together.',
      options: [
        {
          id: 'renew',
          label: 'Renew your vows',
          detail: '−$100 · +8 happiness',
          cost: 100,
          effects: { cash: -100, happiness: 8 },
          ai: 3,
        },
        {
          id: 'skip',
          label: 'A quiet night in',
          detail: '+2 happiness',
          effects: { happiness: 2 },
          ai: 1,
        },
      ],
    };
  }

  if (choiceId === 'nursery' && player.kids >= CONFIG.maxKids) {
    return {
      ...base,
      title: 'Full House',
      prompt: 'The house is loud, joyful, and completely out of bedrooms.',
      options: [
        {
          id: 'full',
          label: 'Enjoy the chaos',
          detail: '+6 happiness',
          effects: { happiness: 6 },
          ai: 2,
        },
      ],
    };
  }

  return base;
}

export function buyProperty(state) {
  assertPending(state, 'buy');
  const player = currentPlayer(state);
  const tile = TILE_BY_ID[state.pending.tileId];
  if (player.cash < tile.price) throw new Error('Not enough cash');
  const events = [];
  player.cash -= tile.price;
  player.stats.assetsBought += 1;
  state.owners[tile.id] = { owner: player.id, level: 1 };
  addLog(state, `${player.name} buys ${tile.name} for $${tile.price}.`, 'buy');
  events.push({ type: 'buy', playerId: player.id, tileId: tile.id, amount: tile.price });
  finishPending(state, events);
  return { events };
}

export function passBuy(state) {
  assertPending(state, 'buy');
  const player = currentPlayer(state);
  const tile = TILE_BY_ID[state.pending.tileId];
  addLog(state, `${player.name} passes on ${tile.name}.`, 'info');
  finishPending(state, [{ type: 'pass', playerId: player.id, tileId: tile.id }]);
  return { events: [{ type: 'pass', playerId: player.id, tileId: tile.id }] };
}

export function upgradeProperty(state) {
  assertPending(state, 'upgrade');
  const player = currentPlayer(state);
  const tile = TILE_BY_ID[state.pending.tileId];
  const own = state.owners[tile.id];
  if (!own || own.owner !== player.id) throw new Error('You do not own this property');
  if (own.level >= 3) throw new Error('Already fully upgraded');
  const cost = upgradeCost(tile, own.level);
  if (player.cash < cost) throw new Error('Not enough cash');
  player.cash -= cost;
  own.level += 1;
  addLog(state, `${player.name} upgrades ${tile.name} to level ${own.level} for $${cost}.`, 'buy');
  const events = [{ type: 'upgrade', playerId: player.id, tileId: tile.id, level: own.level, amount: cost }];
  finishPending(state, events);
  return { events };
}

export function passUpgrade(state) {
  assertPending(state, 'upgrade');
  const player = currentPlayer(state);
  const tile = TILE_BY_ID[state.pending.tileId];
  addLog(state, `${player.name} decides ${tile.name} is fine as it is.`, 'info');
  finishPending(state, [{ type: 'pass', playerId: player.id, tileId: tile.id }]);
  return { events: [{ type: 'pass', playerId: player.id, tileId: tile.id }] };
}

export function acknowledgeCard(state) {
  if (!state.pending || state.pending.type !== 'card') throw new Error('No card to acknowledge');
  state.pending = null;
  state.phase = 'end';
  return { events: [] };
}

export function chooseOption(state, optionId) {
  if (!state.pending || state.pending.type !== 'choice') throw new Error('No choice to resolve');
  const player = currentPlayer(state);
  const choice = choiceFor(state, state.pending.choiceId, player);
  const option = choice.options.find((item) => item.id === optionId);
  if (!option) throw new Error(`Unknown option ${optionId}`);
  if (option.cost && player.cash < option.cost) throw new Error('Not enough cash for that choice');

  const events = [];
  applyEffects(state, player, option.effects || {}, events);

  if (option.gamble) {
    const win = nextRandom(state) < option.gamble.chance;
    if (win) {
      player.cash += option.gamble.win;
      events.push({ type: 'money', playerId: player.id, amount: option.gamble.win, reason: 'investment' });
      addLog(state, `${option.gamble.winText} +$${option.gamble.win}.`, 'good');
    } else {
      addLog(state, `${option.gamble.loseText} −$${option.cost}.`, 'bad');
    }
    events.push({ type: 'gamble', playerId: player.id, win });
  }

  addLog(state, `${player.name} chose “${option.label}”.`, 'choice');
  finishPending(state, events);
  return { events, option };
}

function applyEffects(state, player, effects, events) {
  if (effects.cash) applyCash(state, player, effects.cash, events);
  if (effects.salary) {
    player.salary = Math.max(100, player.salary + effects.salary);
    events.push({ type: 'salaryUp', playerId: player.id, amount: effects.salary });
  }
  if (effects.happiness) applyHappiness(state, player, effects.happiness, events);
  if (effects.partner) {
    player.partner = true;
    events.push({ type: 'family', playerId: player.id, partner: true });
  }
  if (effects.kids) {
    player.kids += effects.kids;
    events.push({ type: 'family', playerId: player.id, kids: player.kids });
  }
  for (const flag of effects.flags || []) player.flags[flag] = true;
}

function finishPending(state, events) {
  state.pending = null;
  state.phase = 'end';
  return events;
}

export function endTurn(state) {
  if (state.phase !== 'end' && state.phase !== 'action') {
    throw new Error(`Cannot end turn during phase ${state.phase}`);
  }
  const events = [];
  const player = currentPlayer(state);
  if (!player.retired && !player.bankrupt && player.laps >= state.laps) {
    player.retired = true;
    player.cash += CONFIG.retirementBonus;
    addLog(state, `${player.name} retires after chapter ${state.laps}. A $${CONFIG.retirementBonus} retirement bonus.`, 'retire');
    events.push({ type: 'retire', playerId: player.id });
  }

  const active = state.players.filter((p) => !p.retired && !p.bankrupt);
  if (active.length === 0) {
    finishGame(state, events);
    return { events, ended: true };
  }

  let next = state.current;
  for (let i = 0; i < state.players.length; i++) {
    next = (next + 1) % state.players.length;
    if (!state.players[next].retired && !state.players[next].bankrupt) break;
  }

  state.current = next;
  state.phase = 'roll';
  state.lastRoll = null;
  state.pending = null;
  state.turn += 1;
  addLog(state, `${state.players[next].name}'s turn.`, 'turn');
  return { events, ended: false };
}

// ---------------------------------------------------------------------------
// Cards, money, bankruptcy
// ---------------------------------------------------------------------------

function drawCard(state, player, events) {
  if (state.deckIndex >= state.deck.length) {
    state.deck = shuffle(state, CARDS.map((card) => card.id));
    state.deckIndex = 0;
    addLog(state, 'The deck is reshuffled.', 'info');
  }
  const card = CARD_BY_ID[state.deck[state.deckIndex++]];
  player.stats.events += 1;

  if (card.cash) {
    const before = player.cash;
    player.cash = Math.max(0, player.cash + card.cash);
    events.push({ type: 'money', playerId: player.id, amount: player.cash - before, reason: card.title });
  }
  if (card.salary) {
    player.salary = Math.max(100, player.salary + card.salary);
    events.push({ type: 'salaryUp', playerId: player.id, amount: card.salary });
  }
  if (card.happiness) applyHappiness(state, player, card.happiness, events);

  state.pending = { type: 'card', cardId: card.id, playerId: player.id };
  addLog(state, `Life event — ${card.title}: ${card.text}`, card.tone);
  return { type: 'card', card, playerId: player.id };
}

function applyCash(state, player, amount, events) {
  player.cash = Math.max(0, player.cash + amount);
  events.push({ type: 'money', playerId: player.id, amount, reason: 'life' });
}

function applyHappiness(state, player, amount, events) {
  const before = player.happiness;
  player.happiness = clamp(player.happiness + amount, 0, 100);
  const delta = player.happiness - before;
  if (delta) events.push({ type: 'happiness', playerId: player.id, amount: delta });
}

function payPlayer(state, from, to, amount, reason) {
  const paid = Math.min(from.cash, amount);
  from.cash -= paid;
  if (to) to.cash += paid;

  if (paid < amount) {
    bankruptPlayer(state, from, to);
  }
  return paid;
}

function bankruptPlayer(state, player, creditor) {
  player.bankrupt = true;
  player.retired = true;
  player.happiness = 0;
  state.pending = null;
  const released = [];
  for (const [tileId, own] of Object.entries(state.owners)) {
    if (own.owner !== player.id) continue;
    if (creditor) {
      own.owner = creditor.id;
      released.push(Number(tileId));
    } else {
      delete state.owners[tileId];
    }
  }
  addLog(state, `${player.name} goes bankrupt and leaves the board.`, 'bad');
  if (released.length) addLog(state, `${creditor.name} takes over their properties.`, 'bad');
}

// ---------------------------------------------------------------------------
// Scoring
// ---------------------------------------------------------------------------

export function scorePlayer(state, player) {
  const owned = Object.entries(state.owners).filter(([, own]) => own.owner === player.id);
  const assets = owned.reduce((sum, [tileId, own]) => sum + assetValue(TILE_BY_ID[Number(tileId)], own.level), 0);
  const goal = GOAL_BY_ID[player.goal];
  const goalMet = !player.bankrupt && goal ? Boolean(goal.check(state, player)) : false;
  const family = (player.partner ? 150 : 0) + player.kids * 120;
  const happiness = player.happiness * 8;
  const retirement = player.retired && !player.bankrupt ? 200 : 0;
  const goalBonus = goalMet ? CONFIG.goalBonus : 0;
  const total = Math.round(player.cash + assets + happiness + family + goalBonus + retirement);

  return {
    playerId: player.id,
    cash: player.cash,
    assets,
    happiness,
    family,
    goal: goalBonus,
    goalMet,
    retirement,
    total,
  };
}

function finishGame(state, events) {
  const results = state.players
    .map((player) => scorePlayer(state, player))
    .sort((a, b) => b.total - a.total || b.cash - a.cash);
  state.phase = 'ended';
  state.results = results;
  state.winner = results[0]?.playerId ?? null;
  state.pending = null;
  const winner = state.players[state.winner];
  addLog(state, `${winner?.name} wins with a life score of ${results[0]?.total}.`, 'retire');
  events.push({ type: 'gameover', winner: state.winner, results });
}

export function isGameOver(state) {
  return state.phase === 'ended';
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function assertPending(state, type) {
  if (!state.pending || state.pending.type !== type) throw new Error(`Expected pending ${type}`);
}

function addLog(state, text, kind = 'info') {
  state.log.push({ id: state.log.length + 1, turn: state.turn, text, kind });
  if (state.log.length > 80) state.log.shift();
}

export function goalProgress(state, player) {
  const goal = GOAL_BY_ID[player.goal];
  if (!goal) return { text: '', met: false };
  switch (goal.id) {
    case 'tycoon':
      return { text: `${Math.min(4, countAssets(state, player.id))}/4 assets`, met: goal.check(state, player) };
    case 'globetrotter':
      return {
        text: `${Math.min(2, countAssets(state, player.id, (tile) => tile.district === 'adventure'))}/2 adventure assets`,
        met: goal.check(state, player),
      };
    case 'family':
      return { text: `${player.partner ? 'Partner ✓' : 'No partner'} · ${Math.min(2, player.kids)}/2 kids`, met: goal.check(state, player) };
    case 'scholar':
      return { text: player.flags.scholar ? 'Graduated ✓' : 'Not yet', met: goal.check(state, player) };
    case 'philanthropist':
      return { text: player.flags.philanthropist ? 'Donated ✓' : 'Not yet', met: goal.check(state, player) };
    case 'homeowner':
      return { text: hasMaxLevelAsset(state, player.id) ? 'Level 3 ✓' : 'No level 3 asset', met: goal.check(state, player) };
    case 'socialite':
      return { text: `${player.happiness}/80 happiness`, met: goal.check(state, player) };
    case 'investor':
      return { text: `$${player.cash}/$2,000`, met: goal.check(state, player) };
    default:
      return { text: '', met: false };
  }
}

export function serialize(state) {
  return JSON.stringify(state);
}

export function deserialize(raw) {
  if (!raw) return null;
  try {
    const state = typeof raw === 'string' ? JSON.parse(raw) : raw;
    if (!state || state.version !== 1) return null;
    if (!Array.isArray(state.players) || !state.players.length) return null;
    if (!TILE_BY_ID[state.players[state.current]?.position ?? -1]) return null;
    if (!['roll', 'moving', 'action', 'end', 'ended'].includes(state.phase)) return null;
    return state;
  } catch {
    return null;
  }
}

import { GROUP_TILES, TILE_BY_ID, upgradeCost } from './data.js';
import { choiceFor, currentPlayer } from './engine.js';

// A friendly, slightly greedy opponent. It values a complete colour group,
// keeps a cash cushion, and generally says yes to love and learning.
export function aiPendingAction(state) {
  const pending = state.pending;
  if (!pending) return null;
  const player = currentPlayer(state);

  if (pending.type === 'buy') {
    const tile = TILE_BY_ID[pending.tileId];
    const completesGroup = (GROUP_TILES[tile.district] || []).filter((id) => id !== tile.id).every(
      (id) => state.owners[id]?.owner === player.id,
    );
    const cushion = completesGroup ? 60 : 220;
    const buy = player.cash - tile.price >= cushion || (tile.price <= 180 && player.cash - tile.price >= 100);
    return { type: buy ? 'buy' : 'pass' };
  }

  if (pending.type === 'upgrade') {
    const tile = TILE_BY_ID[pending.tileId];
    const cost = upgradeCost(tile, state.owners[tile.id].level);
    const groupComplete = (GROUP_TILES[tile.district] || []).every((id) => state.owners[id]?.owner === player.id);
    const upgrade = player.cash - cost >= (groupComplete ? 180 : 380);
    return { type: upgrade ? 'upgrade' : 'skipUpgrade' };
  }

  if (pending.type === 'card') {
    return { type: 'card' };
  }

  if (pending.type === 'choice') {
    const choice = choiceFor(state, pending.choiceId, player);
    const affordable = choice.options.filter((option) => !option.cost || player.cash >= option.cost);
    const pool = affordable.length ? affordable : [choice.options[0]];
    let best = pool[0];
    let bestScore = -Infinity;
    for (const option of pool) {
      let score = option.ai ?? 1;
      if (option.cost) {
        const remaining = player.cash - option.cost;
        if (remaining < 150) score -= 3;
        else if (remaining < 350) score -= 1;
      }
      if (option.gamble && player.cash < 600) score -= 2;
      if (option.id === 'baby' && player.kids >= 2) score -= 2;
      if (score > bestScore) {
        bestScore = score;
        best = option;
      }
    }
    return { type: 'choice', optionId: best.id };
  }

  return null;
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {
  acknowledgeCard,
  buyProperty,
  chooseOption,
  completeMove,
  createGame,
  currentPlayer,
  deserialize,
  endTurn,
  passBuy,
  rollDice,
  scorePlayer,
  serialize,
  upgradeProperty,
} from '../src/game/engine.js';
import { aiPendingAction } from '../src/game/ai.js';
import { CONFIG, TILE_BY_ID, upgradeCost } from '../src/game/data.js';

function game(players = 2, laps = 3) {
  return createGame({
    seed: 42,
    laps,
    players: Array.from({ length: players }, (_, i) => ({
      name: `P${i}`,
      isAI: i > 0,
      color: ['#f00', '#0f0', '#00f', '#ff0'][i],
    })),
  });
}

function landOn(state, tileId) {
  state.phase = 'moving';
  const from = (tileId - 1 + 32) % 32;
  state.players[state.current].position = from;
  state.lastRoll = 1;
  return completeMove(state);
}

test('a new game is deterministic and everyone starts equal', () => {
  const a = game();
  const b = game();
  assert.equal(a.players.length, 2);
  assert.equal(a.players[0].cash, CONFIG.startingCash);
  assert.equal(a.players[0].salary, CONFIG.baseSalary);
  assert.equal(a.players[0].happiness, CONFIG.startingHappiness);
  assert.equal(a.players[0].position, 0);
  assert.notEqual(a.players[0].goal, null);
  assert.deepEqual(a.deck, b.deck);
  assert.deepEqual(
    a.players.map((p) => p.goal),
    b.players.map((p) => p.goal),
  );
});

test('rolling moves along the board and wraps correctly', () => {
  const state = game();
  state.players[0].position = 30;
  const result = rollDice(state);
  assert.equal(state.phase, 'moving');
  assert.equal(result.path.length, result.roll);
  assert.equal(result.to, (30 + result.roll) % 32);
});

test('passing Fresh Start pays salary and starts a new chapter', () => {
  const state = game();
  const player = state.players[0];
  player.position = 31;
  state.phase = 'moving';
  state.lastRoll = 2;
  const { events } = completeMove(state);
  assert.equal(player.position, 1);
  assert.equal(player.laps, 1);
  assert.equal(player.cash, CONFIG.startingCash + CONFIG.baseSalary);
  assert.ok(events.some((e) => e.type === 'salary'));
});

test('landing on an unowned property offers a purchase', () => {
  const state = game();
  const tile = TILE_BY_ID[1];
  landOn(state, 1);
  assert.equal(state.pending.type, 'buy');
  assert.equal(state.phase, 'action');
  buyProperty(state);
  assert.equal(state.owners[1].owner, 0);
  assert.equal(state.owners[1].level, 1);
  assert.equal(state.players[0].cash, CONFIG.startingCash - tile.price);
  assert.equal(state.phase, 'end');
});

test('passing on a property leaves it unowned', () => {
  const state = game();
  landOn(state, 1);
  passBuy(state);
  assert.equal(state.owners[1], undefined);
  assert.equal(state.pending, null);
});

test('rent is paid and a full colour group doubles it', () => {
  const state = game();
  state.owners[1] = { owner: 1, level: 1 };
  state.players[1].cash = 0;
  landOn(state, 1);
  const rent = TILE_BY_ID[1].rent[0];
  assert.equal(state.players[0].cash, CONFIG.startingCash - rent);
  assert.equal(state.players[1].cash, rent);

  // Give player 1 the whole childhood group and land player 0 again.
  for (const id of [3, 5, 7]) state.owners[id] = { owner: 1, level: 1 };
  state.players[0].position = 0;
  state.players[0].cash = 5000;
  state.phase = 'moving';
  state.lastRoll = 1;
  completeMove(state);
  assert.equal(state.players[0].cash, 5000 - rent * CONFIG.groupRentMultiplier);
});

test('upgrading raises the rent and costs the right amount', () => {
  const state = game();
  const tile = TILE_BY_ID[1];
  state.owners[1] = { owner: 0, level: 1 };
  state.players[0].position = 0;
  state.phase = 'moving';
  state.lastRoll = 1;
  completeMove(state);
  assert.equal(state.pending.type, 'upgrade');
  assert.equal(state.pending.cost, upgradeCost(tile, 1));
  upgradeProperty(state);
  assert.equal(state.owners[1].level, 2);
  assert.equal(state.players[0].cash, CONFIG.startingCash - upgradeCost(tile, 1));
});

test('graduation choices apply cash, salary and the scholar flag', () => {
  const state = game();
  landOn(state, 8);
  assert.equal(state.pending.type, 'choice');
  chooseOption(state, 'college');
  const player = state.players[0];
  assert.equal(player.cash, CONFIG.startingCash - 400);
  assert.equal(player.salary, CONFIG.baseSalary + 120);
  assert.equal(player.flags.scholar, true);
  assert.equal(player.happiness, CONFIG.startingHappiness + 6);
  assert.equal(state.phase, 'end');
});

test('choices cannot be bought without cash', () => {
  const state = game();
  state.players[0].cash = 100;
  landOn(state, 8);
  assert.throws(() => chooseOption(state, 'college'), /enough cash/);
});

test('life event cards resolve and can be acknowledged', () => {
  const state = game();
  landOn(state, 2);
  assert.equal(state.pending.type, 'card');
  const cardId = state.pending.cardId;
  assert.ok(cardId);
  acknowledgeCard(state);
  assert.equal(state.pending, null);
  assert.equal(state.phase, 'end');
});

test('retirement triggers after the configured chapters and scores the game', () => {
  const state = game(2, 1);
  const p = state.players[0];
  p.laps = 1;
  state.phase = 'end';
  const { ended } = endTurn(state);
  assert.equal(ended, false);
  assert.equal(p.retired, true);
  assert.equal(p.cash, CONFIG.startingCash + CONFIG.retirementBonus);

  const q = state.players[1];
  q.laps = 1;
  state.phase = 'end';
  const finish = endTurn(state);
  assert.equal(finish.ended, true);
  assert.equal(state.phase, 'ended');
  assert.equal(state.results.length, 2);
  assert.ok(state.results[0].total > 0);
});

test('a player who cannot pay rent goes bankrupt and hands over assets', () => {
  const state = game();
  state.owners[13] = { owner: 1, level: 3 };
  state.players[0].cash = 10;
  landOn(state, 13);
  assert.equal(state.players[0].bankrupt, true);
  assert.equal(state.players[0].cash, 0);
  assert.equal(state.players[1].cash, TILE_BY_ID[13].rent[2]);
  assert.equal(state.phase, 'end');
});

test('AI makes a legal pending decision', () => {
  const state = game();
  landOn(state, 1);
  const action = aiPendingAction(state);
  assert.equal(action.type, 'buy');
  state.players[0].cash = 50;
  landOn(state, 3);
  assert.equal(aiPendingAction(state).type, 'pass');
});

test('game state survives a save/load round trip', () => {
  const state = game();
  state.owners[1] = { owner: 0, level: 2 };
  state.players[0].flags.scholar = true;
  const restored = deserialize(serialize(state));
  assert.equal(restored.players[0].cash, state.players[0].cash);
  assert.equal(restored.owners[1].level, 2);
  assert.equal(restored.players[0].flags.scholar, true);
  assert.equal(restored.deck.length, state.deck.length);
});

test('scores combine cash, assets, happiness and family', () => {
  const state = game();
  const p = state.players[0];
  state.owners[1] = { owner: 0, level: 3 };
  p.cash = 1000;
  p.happiness = 60;
  p.partner = true;
  p.kids = 1;
  const score = scorePlayer(state, p);
  assert.ok(score.assets > 0);
  assert.equal(score.family, 150 + 120);
  assert.equal(score.happiness, 480);
  assert.ok(score.total > 1000);
});

test('currentPlayer tracks endTurn', () => {
  const state = game(3);
  assert.equal(currentPlayer(state).id, 0);
  state.phase = 'end';
  endTurn(state);
  assert.equal(currentPlayer(state).id, 1);
  state.phase = 'end';
  endTurn(state);
  assert.equal(currentPlayer(state).id, 2);
});

// All artwork is drawn procedurally — no external images, no licence worries,
// and every icon stays crisp at any size on any phone.

const TAU = Math.PI * 2;

function roundRect(ctx, x, y, w, h, r) {
  const radius = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.arcTo(x + w, y, x + w, y + h, radius);
  ctx.arcTo(x + w, y + h, x, y + h, radius);
  ctx.arcTo(x, y + h, x, y, radius);
  ctx.arcTo(x, y, x + w, y, radius);
  ctx.closePath();
}

function starPath(ctx, points, outer, inner) {
  ctx.beginPath();
  for (let i = 0; i < points * 2; i++) {
    const radius = i % 2 ? inner : outer;
    const angle = (i * Math.PI) / points - Math.PI / 2;
    const x = Math.cos(angle) * radius;
    const y = Math.sin(angle) * radius;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.closePath();
}

function heartPath(ctx) {
  ctx.beginPath();
  ctx.moveTo(0, 34);
  ctx.bezierCurveTo(-52, -2, -38, -40, -14, -40);
  ctx.bezierCurveTo(-4, -40, 0, -32, 0, -24);
  ctx.bezierCurveTo(0, -32, 4, -40, 14, -40);
  ctx.bezierCurveTo(38, -40, 52, -2, 0, 34);
  ctx.closePath();
}

export function drawIcon(ctx, name, cx, cy, size, color, accent = '#FFFFFF') {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(size / 100, size / 100);
  ctx.fillStyle = color;
  ctx.strokeStyle = color;
  ctx.lineWidth = 8;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  switch (name) {
    case 'sun': {
      ctx.beginPath();
      ctx.arc(0, 0, 20, 0, TAU);
      ctx.fill();
      for (let i = 0; i < 8; i++) {
        const a = (i * TAU) / 8;
        ctx.beginPath();
        ctx.moveTo(Math.cos(a) * 30, Math.sin(a) * 30);
        ctx.lineTo(Math.cos(a) * 43, Math.sin(a) * 43);
        ctx.stroke();
      }
      break;
    }
    case 'cup': {
      ctx.beginPath();
      ctx.moveTo(-24, -28);
      ctx.lineTo(-17, 32);
      ctx.lineTo(17, 32);
      ctx.lineTo(24, -28);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = accent;
      ctx.lineWidth = 7;
      ctx.beginPath();
      ctx.moveTo(-26, -8);
      ctx.lineTo(26, -8);
      ctx.stroke();
      ctx.strokeStyle = color;
      ctx.beginPath();
      ctx.moveTo(12, -30);
      ctx.lineTo(22, -48);
      ctx.stroke();
      break;
    }
    case 'balloon': {
      ctx.beginPath();
      ctx.ellipse(0, -12, 23, 28, 0, 0, TAU);
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(-6, 15);
      ctx.lineTo(0, 24);
      ctx.lineTo(6, 15);
      ctx.closePath();
      ctx.fill();
      ctx.lineWidth = 5;
      ctx.beginPath();
      ctx.moveTo(0, 24);
      ctx.bezierCurveTo(14, 34, -12, 42, 2, 50);
      ctx.stroke();
      break;
    }
    case 'book': {
      ctx.lineWidth = 7;
      ctx.beginPath();
      ctx.moveTo(-44, 28);
      ctx.lineTo(-44, -26);
      ctx.quadraticCurveTo(-24, -34, 0, -20);
      ctx.quadraticCurveTo(24, -34, 44, -26);
      ctx.lineTo(44, 28);
      ctx.quadraticCurveTo(24, 20, 0, 32);
      ctx.quadraticCurveTo(-24, 20, -44, 28);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = accent;
      ctx.lineWidth = 5;
      ctx.beginPath();
      ctx.moveTo(0, -20);
      ctx.lineTo(0, 32);
      ctx.moveTo(-32, -14);
      ctx.quadraticCurveTo(-18, -16, -8, -8);
      ctx.moveTo(-32, 0);
      ctx.quadraticCurveTo(-18, -2, -8, 6);
      ctx.moveTo(32, -14);
      ctx.quadraticCurveTo(18, -16, 8, -8);
      ctx.stroke();
      break;
    }
    case 'star': {
      starPath(ctx, 5, 44, 19);
      ctx.fill();
      break;
    }
    case 'ball': {
      ctx.lineWidth = 7;
      ctx.beginPath();
      ctx.arc(0, 0, 34, 0, TAU);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(-18, 0, 34, -0.85, 0.85);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(18, 0, 34, Math.PI - 0.85, Math.PI + 0.85);
      ctx.stroke();
      break;
    }
    case 'gift': {
      roundRect(ctx, -32, -12, 64, 44, 6);
      ctx.fill();
      roundRect(ctx, -38, -26, 76, 18, 5);
      ctx.fill();
      ctx.fillStyle = accent;
      ctx.fillRect(-7, -26, 14, 58);
      ctx.fillRect(-38, -20, 76, 8);
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.ellipse(-16, -34, 13, 9, -0.5, 0, TAU);
      ctx.fill();
      ctx.beginPath();
      ctx.ellipse(16, -34, 13, 9, 0.5, 0, TAU);
      ctx.fill();
      break;
    }
    case 'blocks': {
      roundRect(ctx, -36, 2, 32, 32, 5);
      ctx.fill();
      roundRect(ctx, 4, 2, 32, 32, 5);
      ctx.fill();
      roundRect(ctx, -16, -32, 32, 32, 5);
      ctx.fill();
      ctx.fillStyle = accent;
      ctx.font = 'bold 22px Fredoka, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('A', -20, 18);
      ctx.fillText('B', 20, 18);
      ctx.fillText('C', 0, -16);
      break;
    }
    case 'cap': {
      ctx.beginPath();
      ctx.moveTo(0, -24);
      ctx.lineTo(44, -6);
      ctx.lineTo(0, 12);
      ctx.lineTo(-44, -6);
      ctx.closePath();
      ctx.fill();
      roundRect(ctx, -20, 4, 40, 14, 5);
      ctx.fill();
      ctx.lineWidth = 5;
      ctx.beginPath();
      ctx.moveTo(34, -1);
      ctx.lineTo(38, 28);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(38, 30, 5, 0, TAU);
      ctx.fill();
      break;
    }
    case 'briefcase': {
      roundRect(ctx, -42, -18, 84, 52, 9);
      ctx.fill();
      ctx.strokeStyle = accent;
      ctx.lineWidth = 7;
      roundRect(ctx, -15, -34, 30, 20, 5);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(-42, 2);
      ctx.lineTo(42, 2);
      ctx.stroke();
      ctx.fillStyle = accent;
      roundRect(ctx, -8, -6, 16, 14, 3);
      ctx.fill();
      break;
    }
    case 'laptop': {
      roundRect(ctx, -34, -34, 68, 44, 5);
      ctx.fill();
      ctx.fillStyle = accent;
      roundRect(ctx, -26, -26, 52, 28, 2);
      ctx.fill();
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.moveTo(-44, 18);
      ctx.lineTo(44, 18);
      ctx.lineTo(32, 32);
      ctx.lineTo(-32, 32);
      ctx.closePath();
      ctx.fill();
      break;
    }
    case 'coffee': {
      ctx.beginPath();
      ctx.moveTo(-26, -22);
      ctx.lineTo(-20, 34);
      ctx.lineTo(20, 34);
      ctx.lineTo(26, -22);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = color;
      ctx.lineWidth = 8;
      ctx.beginPath();
      ctx.arc(30, 2, 13, -1.2, 1.2);
      ctx.stroke();
      ctx.strokeStyle = accent;
      ctx.lineWidth = 5;
      ctx.beginPath();
      ctx.moveTo(-8, -34);
      ctx.bezierCurveTo(-16, -42, 0, -46, -8, -54);
      ctx.moveTo(10, -32);
      ctx.bezierCurveTo(2, -40, 18, -44, 10, -52);
      ctx.stroke();
      break;
    }
    case 'medal': {
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.moveTo(-22, -46);
      ctx.lineTo(-6, -10);
      ctx.lineTo(-30, -16);
      ctx.closePath();
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(22, -46);
      ctx.lineTo(6, -10);
      ctx.lineTo(30, -16);
      ctx.closePath();
      ctx.fill();
      ctx.beginPath();
      ctx.arc(0, 10, 28, 0, TAU);
      ctx.fill();
      ctx.fillStyle = accent;
      starPath(ctx, 5, 16, 7);
      ctx.fill();
      break;
    }
    case 'rocket': {
      ctx.beginPath();
      ctx.moveTo(0, -48);
      ctx.bezierCurveTo(22, -30, 24, -2, 16, 22);
      ctx.lineTo(-16, 22);
      ctx.bezierCurveTo(-24, -2, -22, -30, 0, -48);
      ctx.closePath();
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(-16, 10);
      ctx.lineTo(-36, 32);
      ctx.lineTo(-16, 28);
      ctx.closePath();
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(16, 10);
      ctx.lineTo(36, 32);
      ctx.lineTo(16, 28);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = accent;
      ctx.beginPath();
      ctx.arc(0, -14, 9, 0, TAU);
      ctx.fill();
      ctx.fillStyle = '#FF9F43';
      ctx.beginPath();
      ctx.moveTo(-9, 24);
      ctx.lineTo(0, 48);
      ctx.lineTo(9, 24);
      ctx.closePath();
      ctx.fill();
      break;
    }
    case 'moon': {
      ctx.beginPath();
      ctx.arc(0, 0, 38, 0, TAU);
      ctx.fill();
      ctx.globalCompositeOperation = 'destination-out';
      ctx.beginPath();
      ctx.arc(16, -10, 30, 0, TAU);
      ctx.fill();
      ctx.globalCompositeOperation = 'source-over';
      ctx.fillStyle = color;
      starPath(ctx, 5, 10, 4);
      ctx.save();
      ctx.translate(30, 20);
      ctx.fill();
      ctx.restore();
      break;
    }
    case 'compass': {
      ctx.lineWidth = 8;
      ctx.beginPath();
      ctx.arc(0, 0, 38, 0, TAU);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, -32);
      ctx.lineTo(10, 0);
      ctx.lineTo(0, 32);
      ctx.lineTo(-10, 0);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = accent;
