    case 'crib': {
      ctx.lineWidth = 7;
      roundRect(ctx, -36, -18, 72, 40, 6);
      ctx.stroke();
      for (let i = -24; i <= 24; i += 12) {
        ctx.beginPath();
        ctx.moveTo(i, -18);
        ctx.lineTo(i, 22);
        ctx.stroke();
      }
      ctx.beginPath();
      ctx.moveTo(-36, -18);
      ctx.lineTo(-36, -36);
      ctx.lineTo(36, -36);
      ctx.lineTo(36, -18);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(-30, 22);
      ctx.lineTo(-38, 40);
      ctx.moveTo(30, 22);
      ctx.lineTo(38, 40);
      ctx.stroke();
      break;
    }
    case 'plane': {
      ctx.beginPath();
      ctx.moveTo(46, -36);
      ctx.lineTo(-36, -6);
      ctx.lineTo(-4, 6);
      ctx.lineTo(8, 38);
      ctx.lineTo(20, 12);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = accent;
      ctx.lineWidth = 5;
      ctx.beginPath();
      ctx.moveTo(-36, -6);
      ctx.lineTo(20, 12);
      ctx.stroke();
