    }
    case 'flower': {
      ctx.fillStyle = color;
      for (let i = 0; i < 6; i++) {
        const a = (i * TAU) / 6;
        ctx.beginPath();
        ctx.ellipse(Math.cos(a) * 20, -12 + Math.sin(a) * 20, 13, 9, a, 0, TAU);
        ctx.fill();
      }
      ctx.fillStyle = '#FFD166';
      ctx.beginPath();
      ctx.arc(0, -12, 10, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = color;
      ctx.lineWidth = 6;
      ctx.beginPath();
      ctx.moveTo(0, 4);
      ctx.quadraticCurveTo(-6, 28, 0, 46);
      ctx.stroke();
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.ellipse(-14, 26, 13, 7, -0.6, 0, TAU);
      ctx.fill();
      break;
    }
    case 'shop': {
      roundRect(ctx, -38, -10, 76, 50, 5);
      ctx.fill();
      ctx.fillStyle = accent;
      roundRect(ctx, -22, 6, 20, 34, 3);
      ctx.fill();
      roundRect(ctx, 8, 6, 20, 20, 3);
      ctx.fill();
      ctx.fillStyle = color;
      for (let i = 0; i < 4; i++) {
        ctx.beginPath();
        ctx.arc(-30 + i * 20, -10, 10, Math.PI, 0);
        ctx.fill();
      }
      ctx.fillRect(-40, -14, 80, 8);
      break;
    }
    case 'nest': {
      ctx.lineWidth = 8;
      ctx.beginPath();
      ctx.arc(0, 8, 34, 0.15, Math.PI - 0.15);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(0, 8, 26, 0.1, Math.PI - 0.1);
      ctx.stroke();
      ctx.fillStyle = accent;
      ctx.beginPath();
      ctx.ellipse(-10, 0, 11, 14, 0.2, 0, TAU);
      ctx.fill();
      ctx.beginPath();
      ctx.ellipse(12, 2, 10, 13, -0.2, 0, TAU);
      ctx.fill();
      break;
    }
    case 'globe': {
      ctx.lineWidth = 7;
      ctx.beginPath();
      ctx.arc(0, 0, 36, 0, TAU);
      ctx.stroke();
      ctx.beginPath();
      ctx.ellipse(0, 0, 16, 36, 0, 0, TAU);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(-36, 0);
      ctx.lineTo(36, 0);
      ctx.stroke();
      ctx.beginPath();
      ctx.ellipse(0, 0, 34, 14, 0, 0, TAU);
      ctx.stroke();
      break;
    }
    case 'umbrella': {
      ctx.beginPath();
      ctx.arc(0, -6, 42, Math.PI, 0);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = color;
      ctx.lineWidth = 7;
      ctx.beginPath();
      ctx.moveTo(0, -6);
      ctx.lineTo(0, 34);
      ctx.arc(-10, 34, 10, 0, Math.PI);
      ctx.stroke();
      break;
    }
    case 'mountain': {
      ctx.beginPath();
      ctx.moveTo(-46, 36);
      ctx.lineTo(-8, -38);
      ctx.lineTo(30, 36);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = accent;
      ctx.beginPath();
      ctx.moveTo(-20, -16);
      ctx.lineTo(-8, -38);
      ctx.lineTo(4, -16);
      ctx.lineTo(-4, -10);
      ctx.lineTo(-11, -18);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.moveTo(6, 36);
      ctx.lineTo(32, -12);
      ctx.lineTo(48, 36);
      ctx.closePath();
      ctx.fill();
      break;
    }
    case 'palette': {
      ctx.beginPath();
      ctx.ellipse(0, 0, 42, 36, 0, 0, TAU);
      ctx.fill();
      ctx.fillStyle = accent;
      ctx.beginPath();
      ctx.ellipse(20, 16, 11, 9, 0.4, 0, TAU);
      ctx.fill();
      const dots = [
        [-20, -14, '#FF7A6B'],
        [-2, -24, '#5B8DEF'],
        [18, -18, '#FFC44D'],
        [-24, 8, '#59C08A'],
      ];
      for (const [x, y, c] of dots) {
        ctx.fillStyle = c;
        ctx.beginPath();
        ctx.arc(x, y, 6, 0, TAU);
        ctx.fill();
      }
      break;
    }
    case 'chart': {
      ctx.fillStyle = color;
      roundRect(ctx, -36, 12, 16, 28, 3);
      ctx.fill();
      roundRect(ctx, -12, 0, 16, 40, 3);
      ctx.fill();
      roundRect(ctx, 12, -18, 16, 58, 3);
      ctx.fill();
      ctx.strokeStyle = color;
      ctx.lineWidth = 6;
      ctx.beginPath();
      ctx.moveTo(-34, 2);
      ctx.lineTo(-2, -18);
      ctx.lineTo(20, -28);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(20, -28);
      ctx.lineTo(8, -30);
      ctx.moveTo(20, -28);
      ctx.lineTo(22, -16);
      ctx.stroke();
      break;
    }
    case 'car': {
      ctx.beginPath();
      ctx.moveTo(-44, 14);
      ctx.lineTo(-34, -4);
      ctx.lineTo(-12, -8);
      ctx.lineTo(-2, -26);
      ctx.lineTo(22, -26);
      ctx.lineTo(32, -8);
      ctx.lineTo(42, -2);
      ctx.lineTo(42, 14);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = accent;
      roundRect(ctx, -2, -22, 22, 12, 2);
      ctx.fill();
      ctx.fillStyle = '#26304A';
      ctx.beginPath();
      ctx.arc(-24, 18, 11, 0, TAU);
      ctx.fill();
      ctx.beginPath();
      ctx.arc(26, 18, 11, 0, TAU);
      ctx.fill();
      ctx.fillStyle = '#DDE6F5';
      ctx.beginPath();
      ctx.arc(-24, 18, 4, 0, TAU);
      ctx.fill();
      ctx.beginPath();
      ctx.arc(26, 18, 4, 0, TAU);
      ctx.fill();
      break;
    }
    case 'coin': {
      ctx.beginPath();
      ctx.arc(0, 0, 36, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = accent;
      ctx.lineWidth = 6;
      ctx.beginPath();
      ctx.arc(0, 0, 27, 0, TAU);
      ctx.stroke();
      ctx.fillStyle = accent;
      ctx.font = 'bold 42px Fredoka, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('$', 0, 2);
      break;
    }
    case 'question': {
      ctx.font = 'bold 96px Fredoka, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('?', 0, 6);
      break;
    }
    case 'flag': {
      ctx.lineWidth = 8;
      ctx.beginPath();
      ctx.moveTo(-20, 44);
      ctx.lineTo(-20, -40);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(-18, -38);
      ctx.lineTo(40, -22);
      ctx.lineTo(-18, -4);
      ctx.closePath();
      ctx.fill();
      break;
    }
    case 'trophy': {
      ctx.beginPath();
      ctx.moveTo(-26, -38);
      ctx.lineTo(26, -38);
      ctx.lineTo(22, 2);
      ctx.quadraticCurveTo(0, 20, -22, 2);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = color;
      ctx.lineWidth = 7;
      ctx.beginPath();
      ctx.arc(-30, -22, 12, -1.2, 1.2);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(30, -22, 12, Math.PI - 1.2, Math.PI + 1.2);
      ctx.stroke();
      ctx.fillRect(-6, 14, 12, 18);
      roundRect(ctx, -22, 32, 44, 10, 3);
      ctx.fill();
      break;
    }
    default: {
      ctx.beginPath();
      ctx.arc(0, 0, 28, 0, TAU);
      ctx.fill();
    }
  }

  ctx.restore();
}

export function iconDataURL(name, color, size = 96, background = 'transparent') {
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (background !== 'transparent') {
    ctx.fillStyle = background;
    ctx.fillRect(0, 0, size, size);
  }
  drawIcon(ctx, name, size / 2, size / 2, size * 0.9, color);
  return canvas.toDataURL('image/png');
}

export function roundedRectPath(ctx, x, y, w, h, r) {
  roundRect(ctx, x, y, w, h, r);
}

