@import '@fontsource/fredoka/400.css';
@import '@fontsource/fredoka/500.css';
@import '@fontsource/fredoka/600.css';
@import '@fontsource/fredoka/700.css';
@import '@fontsource/nunito/400.css';
@import '@fontsource/nunito/600.css';
@import '@fontsource/nunito/700.css';
@import '@fontsource/nunito/800.css';

:root {
  --ink: #22304c;
  --ink-soft: #5b6b86;
  --cream: #fff8ea;
  --paper: #fffdf7;
  --navy: #101b33;
  --navy-2: #17263f;
  --gold: #ffc94a;
  --gold-deep: #e9a91f;
  --coral: #ff7a6b;
  --teal: #35c4b5;
  --pink: #f08bad;
  --violet: #9c7bf3;
  --green: #59c08a;
  --blue: #5b8def;
  --shadow: 0 18px 50px rgba(20, 30, 60, 0.18);
  --radius: 22px;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
}

* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

html,
body {
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: #cfeaff;
  color: var(--ink);
  font-family: 'Nunito', system-ui, -apple-system, 'Segoe UI', sans-serif;
  overscroll-behavior: none;
}

body {
  position: fixed;
  inset: 0;
  user-select: none;
  -webkit-user-select: none;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
}

#app {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
}

#scene-container {
  position: absolute;
  inset: 0;
  z-index: 0;
}

#scene-container canvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
}

#vignette {
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background:
    radial-gradient(120% 90% at 50% 42%, transparent 55%, rgba(16, 27, 51, 0.18) 100%),
    linear-gradient(to top, rgba(16, 27, 51, 0.32), transparent 28%);
}

#ui {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
}

.hidden {
  display: none !important;
}

button,
.interactive {
  pointer-events: auto;
}

/* ------------------------------------------------------------------ */
/* Shared bits                                                         */
/* ------------------------------------------------------------------ */

.pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border-radius: 999px;
  padding: 6px 12px;
  font-weight: 800;
  font-size: 12px;
  letter-spacing: 0.04em;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  border-radius: 16px;
  padding: 13px 20px;
  font-family: 'Fredoka', sans-serif;
  font-weight: 600;
  font-size: 17px;
  letter-spacing: 0.01em;
  background: var(--gold);
  color: #3a2a00;
  box-shadow: 0 6px 0 #d69a12, 0 12px 22px rgba(60, 40, 0, 0.22);
  transition: transform 0.12s ease, box-shadow 0.12s ease, filter 0.12s ease;
}

.btn:hover {
  filter: brightness(1.04);
}

.btn:active {
  transform: translateY(3px);
  box-shadow: 0 3px 0 #d69a12, 0 6px 12px rgba(60, 40, 0, 0.2);
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  filter: saturate(0.4);
  box-shadow: 0 4px 0 rgba(0, 0, 0, 0.15);
}

.btn.secondary {
  background: var(--cream);
  color: var(--ink);
  box-shadow: 0 5px 0 #d9c7a8, 0 10px 20px rgba(20, 30, 60, 0.12);
}

.btn.ghost {
  background: rgba(255, 255, 255, 0.12);
  color: var(--cream);
  border: 1px solid rgba(255, 255, 255, 0.22);
  box-shadow: none;
}

.btn.small {
  padding: 9px 14px;
  font-size: 14px;
  border-radius: 12px;
  box-shadow: 0 4px 0 #d69a12, 0 8px 14px rgba(60, 40, 0, 0.16);
}

.btn.danger {
  background: #ff8c7d;
  color: #4a120c;
  box-shadow: 0 5px 0 #c04f40;
}

.icon-btn {
  width: 42px;
  height: 42px;
  border-radius: 14px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.14);
  color: var(--cream);
  border: 1px solid rgba(255, 255, 255, 0.18);
  backdrop-filter: blur(10px);
  transition: background 0.15s ease, transform 0.15s ease;
}

.icon-btn:hover {
  background: rgba(255, 255, 255, 0.24);
}

.icon-btn:active {
  transform: scale(0.94);
}

.icon-btn svg {
  width: 20px;
  height: 20px;
}

/* ------------------------------------------------------------------ */
/* Start screen                                                        */
/* ------------------------------------------------------------------ */

#start-screen {
  position: absolute;
  inset: 0;
  z-index: 10;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: calc(24px + var(--safe-top)) clamp(20px, 4vw, 64px) calc(22px + var(--safe-bottom));
  pointer-events: none;
  background: linear-gradient(90deg, rgba(16, 27, 51, 0.55) 0%, rgba(16, 27, 51, 0.18) 42%, transparent 68%);
}

#start-screen::after {
  content: '';
  position: absolute;
  inset: auto 0 0 0;
  height: 38%;
  background: linear-gradient(to top, rgba(16, 27, 51, 0.6), transparent);
  pointer-events: none;
}

.start-top {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.brand-lockup {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--cream);
}

.brand-mark {
  width: 46px;
  height: 46px;
  border-radius: 14px;
  background: linear-gradient(145deg, #ffd166, #ff9f43);
  display: grid;
  place-items: center;
  font-family: 'Fredoka', sans-serif;
  font-size: 26px;
  font-weight: 700;
  color: #4a2c00;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.25);
  transform: rotate(-6deg);
}

.brand-text {
  display: flex;
  flex-direction: column;
  line-height: 1;
}

.brand-text strong {
  font-family: 'Fredoka', sans-serif;
  font-size: 17px;
  letter-spacing: 0.16em;
}

.brand-text span {
  font-size: 10px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(255, 248, 234, 0.65);
  margin-top: 5px;
}

.start-main {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(340px, 0.85fr);
  align-items: end;
  gap: clamp(24px, 5vw, 80px);
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  pointer-events: none;
}

.hero {
  color: var(--cream);
  max-width: 620px;
  padding-bottom: 10px;
  text-shadow: 0 4px 30px rgba(10, 20, 40, 0.35);
}

.hero-kicker {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-weight: 800;
  font-size: 11px;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--gold);
  margin-bottom: 18px;
}

.hero-kicker::before {
  content: '';
  width: 30px;
  height: 2px;
  background: var(--gold);
  border-radius: 2px;
}

.hero h1 {
  font-family: 'Fredoka', sans-serif;
  font-weight: 700;
  font-size: clamp(58px, 8.2vw, 112px);
  line-height: 0.82;
  letter-spacing: -0.035em;
  margin: 0 0 22px;
  color: #fff9ec;
}

.hero h1 .line {
  display: block;
}

.hero h1 .outline {
  color: transparent;
  -webkit-text-stroke: 2px rgba(255, 249, 236, 0.9);
  font-size: 0.62em;
  letter-spacing: 0.01em;
  margin: 0.08em 0 0.02em 0.08em;
}

.hero h1 .accent {
  color: var(--gold);
}

.hero p {
  font-size: clamp(15px, 1.4vw, 19px);
  line-height: 1.55;
  max-width: 430px;
  color: rgba(255, 248, 234, 0.82);
  margin: 0;
}

.hero-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 22px;
}

.hero-badges span {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 7px 11px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.16);
  color: rgba(255, 248, 234, 0.85);
  backdrop-filter: blur(8px);
}

.setup-card {
  pointer-events: auto;
  background: rgba(255, 250, 240, 0.94);
  backdrop-filter: blur(18px);
  border-radius: 28px;
  padding: clamp(20px, 2.4vw, 30px);
  box-shadow: 0 30px 80px rgba(10, 20, 40, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.7);
  max-width: 420px;
  width: 100%;
  justify-self: end;
}

.setup-card h2 {
  font-family: 'Fredoka', sans-serif;
  font-size: 26px;
  margin: 0 0 4px;
  color: var(--ink);
}

.setup-card .sub {
  font-size: 13px;
  color: var(--ink-soft);
  margin: 0 0 18px;
  line-height: 1.5;
}

.field {
  margin-bottom: 15px;
}

.field-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: #8a7a63;
  margin-bottom: 7px;
}

.segmented {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 1fr;
  gap: 4px;
  padding: 4px;
  border-radius: 14px;
  background: #f0e6d4;
}

.segmented button {
  padding: 9px 6px;
  border-radius: 10px;
  font-size: 13px;
  font-weight: 800;
  color: #7c6a52;
  transition: background 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
  white-space: nowrap;
}

.segmented button.active {
  background: #fffdf7;
  color: var(--ink);
  box-shadow: 0 3px 10px rgba(90, 70, 40, 0.12);
}

.segmented button:disabled {
  opacity: 0.4;
}

.setup-actions {
  display: flex;
  flex-direction: column;
  gap: 9px;
  margin-top: 20px;
}

.setup-actions .btn {
  width: 100%;
}

.setup-actions .row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9px;
}

.continue-btn {
  background: #d9f4ee;
  color: #0b6b62;
  box-shadow: 0 5px 0 #a9d9cf, 0 10px 18px rgba(20, 80, 70, 0.12);
}

.start-footer {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  color: rgba(255, 248, 234, 0.55);
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  max-width: 1280px;
  width: 100%;
  margin: 0 auto;
}

.sound-toggle {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: rgba(255, 248, 234, 0.8);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  pointer-events: auto;
  padding: 8px 12px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(8px);
}

.sound-toggle .dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 10px var(--green);
}

.sound-toggle.off .dot {
  background: #9aa5b8;
  box-shadow: none;
}

/* ------------------------------------------------------------------ */
/* HUD                                                                 */
/* ------------------------------------------------------------------ */

#hud {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  padding: calc(12px + var(--safe-top)) clamp(12px, 2vw, 24px) calc(12px + var(--safe-bottom));
  pointer-events: none;
}

.hud-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  flex-shrink: 0;
}

.hud-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  pointer-events: auto;
  color: var(--cream);
  text-shadow: 0 2px 12px rgba(10, 20, 40, 0.35);
}

.hud-brand .brand-mark {
  width: 36px;
  height: 36px;
  border-radius: 11px;
  font-size: 20px;
}

.hud-brand .brand-text strong {
  font-size: 13px;
}

.hud-brand .brand-text span {
  font-size: 8px;
}

.chapter-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(16, 27, 51, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.15);
  backdrop-filter: blur(12px);
  color: var(--cream);
  padding: 7px 13px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-top: 4px;
}

.chapter-pill .chapter-dots {
  display: inline-flex;
  gap: 4px;
}

.chapter-pill .chapter-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.25);
}

.chapter-pill .chapter-dot.done {
  background: var(--gold);
}

.hud-actions {
  display: flex;
  gap: 8px;
  pointer-events: auto;
}

.hud-main {
  flex: 1;
  display: grid;
  grid-template-columns: 260px minmax(0, 1fr) 280px;
  gap: 16px;
  align-items: start;
  min-height: 0;
  padding-top: 16px;
  pointer-events: none;
}

.players-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
  pointer-events: auto;
}

.player-card {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  gap: 10px;
  align-items: center;
  padding: 9px 11px;
  border-radius: 16px;
  background: rgba(255, 250, 240, 0.9);
  border: 1px solid rgba(255, 255, 255, 0.6);
  box-shadow: 0 8px 24px rgba(16, 27, 51, 0.14);
  backdrop-filter: blur(14px);
  transition: transform 0.2s ease, box-shadow 0.2s ease, opacity 0.2s ease;
  position: relative;
  overflow: hidden;
}

.player-card::before {
  content: '';
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  background: var(--player-color, var(--coral));
  opacity: 0.9;
}

.player-card.active {
  transform: translateX(4px);
  box-shadow: 0 10px 30px rgba(16, 27, 51, 0.2), 0 0 0 2px var(--player-color, var(--coral));
}

.player-card.retired {
  opacity: 0.62;
}

.player-avatar {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-family: 'Fredoka', sans-serif;
  font-weight: 700;
  font-size: 16px;
  color: #fff;
  background: var(--player-color, var(--coral));
  box-shadow: inset 0 -4px 0 rgba(0, 0, 0, 0.16);
  position: relative;
}

.player-avatar::after {
  content: '';
  position: absolute;
  inset: 4px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.35);
}

.player-card .p-name {
  font-family: 'Fredoka', sans-serif;
  font-weight: 600;
  font-size: 15px;
  line-height: 1.1;
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--ink);
}

.player-card .p-name .tag {
  font-family: 'Nunito', sans-serif;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 2px 5px;
  border-radius: 999px;
  background: #e7edf7;
  color: #64748b;
}

.player-card.active .p-name .tag {
  background: var(--player-color, var(--coral));
  color: #fff;
}

.player-stats {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 3px;
  font-size: 11px;
  font-weight: 800;
  color: #64748b;
}

.player-stats .cash {
  color: #1f7a5c;
  font-variant-numeric: tabular-nums;
}

.player-stats .joy {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-variant-numeric: tabular-nums;
}

.joy-bar {
  width: 46px;
  height: 4px;
  border-radius: 999px;
  background: #e6ddcc;
  overflow: hidden;
}

.joy-bar i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #ffb44d, #ff7a6b);
}

.player-goal {
  font-size: 10px;
  color: #8a7a63;
  margin-top: 4px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.player-goal b {
  color: #5d4b33;
}

.player-goal.met {
  color: #1f7a5c;
}

/* Center column: turn banner + log */
.center-column {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  min-height: 0;
  pointer-events: none;
}

.turn-banner {
  margin-top: 4px;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 8px 15px;
  border-radius: 999px;
  background: rgba(16, 27, 51, 0.58);
  border: 1px solid rgba(255, 255, 255, 0.16);
  backdrop-filter: blur(12px);
  color: var(--cream);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  box-shadow: 0 10px 26px rgba(16, 27, 51, 0.18);
  transition: opacity 0.3s ease, transform 0.3s ease;
}

.turn-banner .dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--player-color, var(--coral));
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--player-color, var(--coral)) 30%, transparent);
}

.turn-banner.enter {
  animation: banner-in 0.45s cubic-bezier(0.2, 1.4, 0.4, 1);
}

@keyframes banner-in {
  from {
    opacity: 0;
    transform: translateY(-10px) scale(0.94);
  }
}

.log-panel {
  width: 100%;
  max-width: 430px;
  display: flex;
  flex-direction: column;
  gap: 5px;
  align-self: flex-end;
  margin-bottom: 8px;
  pointer-events: none;
}

.log-entry {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 11px;
  line-height: 1.4;
  color: rgba(255, 248, 234, 0.9);
  text-shadow: 0 1px 6px rgba(10, 20, 40, 0.6);
  animation: log-in 0.35s ease both;
}

.log-entry .log-dot {
  flex: 0 0 auto;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  margin-top: 5px;
  background: var(--gold);
}

.log-entry.money .log-dot {
  background: #7ee2b8;
}
.log-entry.buy .log-dot {
  background: #9fc0ff;
}
.log-entry.bad .log-dot {
  background: #ff8c7d;
}
.log-entry.happy .log-dot {
  background: #ffb0c8;
}

@keyframes log-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
}

/* Right column: goal / event hints */
.side-panel {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 10px;
  pointer-events: auto;
}

.side-note {
  max-width: 270px;
  padding: 12px 14px;
  border-radius: 16px;
  background: rgba(255, 250, 240, 0.88);
  border: 1px solid rgba(255, 255, 255, 0.6);
  backdrop-filter: blur(14px);
  box-shadow: 0 8px 24px rgba(16, 27, 51, 0.12);
  font-size: 11px;
  line-height: 1.45;
  color: #5b6b86;
}

.side-note strong {
  display: block;
  font-family: 'Fredoka', sans-serif;
  font-size: 13px;
  color: var(--ink);
  margin-bottom: 3px;
}

/* Dock */
.hud-bottom {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding-top: 8px;
}

.dock {
  pointer-events: auto;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px;
  border-radius: 22px;
  background: rgba(16, 27, 51, 0.72);
  border: 1px solid rgba(255, 255, 255, 0.14);
  backdrop-filter: blur(18px);
  box-shadow: 0 20px 50px rgba(10, 20, 40, 0.35);
}

.dock .die-preview {
  width: 54px;
  height: 54px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: linear-gradient(145deg, #fffdf7, #f0dfc2);
  box-shadow: inset 0 -4px 0 rgba(140, 110, 70, 0.2);
}

.dock .die-preview svg {
  width: 34px;
  height: 34px;
}

.dock .roll-btn {
  min-width: 190px;
  height: 54px;
  border-radius: 15px;
  font-size: 18px;
}

.dock .end-btn {
  min-width: 160px;
  height: 54px;
  border-radius: 15px;
  background: #e7f8f2;
  color: #0b6b62;
  box-shadow: 0 5px 0 #a9d9cf, 0 10px 18px rgba(20, 80, 70, 0.16);
}

.dock .hint {
  color: rgba(255, 248, 234, 0.72);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  padding: 0 12px;
  max-width: 260px;
  text-align: center;
  line-height: 1.35;
}

.dock.busy {
  opacity: 0.9;
}

.thinking {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.thinking i {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: currentColor;
  animation: think 1s infinite ease-in-out;
}
.thinking i:nth-child(2) {
  animation-delay: 0.15s;
}
.thinking i:nth-child(3) {
  animation-delay: 0.3s;
}

@keyframes think {
  0%,
  80%,
  100% {
    opacity: 0.25;
    transform: translateY(0);
  }
  40% {
    opacity: 1;
    transform: translateY(-3px);
  }
}

/* Mobile player strip */
.mobile-players {
  display: none;
}

/* Toasts + floaters */
#toasts {
  position: absolute;
  top: calc(70px + var(--safe-top));
  left: 50%;
  transform: translateX(-50%);
  z-index: 30;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  pointer-events: none;
  width: min(92vw, 420px);
}

.toast {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 15px;
  border-radius: 999px;
  background: rgba(16, 27, 51, 0.86);
  border: 1px solid rgba(255, 255, 255, 0.15);
  backdrop-filter: blur(12px);
  color: var(--cream);
  font-size: 12px;
  font-weight: 800;
  box-shadow: 0 12px 30px rgba(10, 20, 40, 0.25);
  animation: toast-in 0.3s cubic-bezier(0.2, 1.2, 0.4, 1) both;
  white-space: nowrap;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
}

.toast.out {
  animation: toast-out 0.3s ease both;
}

.toast.good {
  background: rgba(16, 92, 70, 0.9);
}
.toast.bad {
  background: rgba(132, 45, 38, 0.9);
}
.toast.gold {
  background: rgba(120, 82, 4, 0.9);
}

@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(-8px) scale(0.94);
  }
}
@keyframes toast-out {
  to {
    opacity: 0;
    transform: translateY(-8px) scale(0.96);
  }
}

#floaters {
  position: absolute;
  inset: 0;
  z-index: 25;
  pointer-events: none;
  overflow: hidden;
}

.floater {
  position: absolute;
  transform: translate(-50%, -50%);
  font-family: 'Fredoka', sans-serif;
  font-weight: 700;
  font-size: 22px;
  color: #fff6e6;
  text-shadow: 0 2px 0 rgba(90, 50, 0, 0.25), 0 6px 18px rgba(10, 20, 40, 0.45);
  animation: float-up 1.4s ease-out forwards;
  white-space: nowrap;
}

.floater.negative {
  color: #ffb4a8;
}
.floater.joy {
  color: #ffc6d9;
}

@keyframes float-up {
  0% {
    opacity: 0;
    transform: translate(-50%, -30%) scale(0.8);
  }
  18% {
    opacity: 1;
    transform: translate(-50%, -60%) scale(1.05);
  }
  100% {
    opacity: 0;
    transform: translate(-50%, -160%) scale(1);
  }
}

/* ------------------------------------------------------------------ */
/* Modals                                                              */
/* ------------------------------------------------------------------ */

#modal-root {
  position: absolute;
  inset: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(18px + var(--safe-top)) 18px calc(18px + var(--safe-bottom));
  pointer-events: none;
}

.modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(10, 18, 34, 0.55);
  backdrop-filter: blur(6px);
  opacity: 0;
  transition: opacity 0.25s ease;
  pointer-events: auto;
}

.modal-backdrop.show {
  opacity: 1;
}

.modal {
  position: relative;
  width: min(94vw, 480px);
  max-height: min(88vh, 760px);
  overflow: auto;
  border-radius: 26px;
  background: var(--paper);
  box-shadow: 0 40px 100px rgba(5, 12, 26, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.9);
  transform: translateY(18px) scale(0.96);
  opacity: 0;
  transition: transform 0.3s cubic-bezier(0.2, 1.3, 0.4, 1), opacity 0.25s ease;
  pointer-events: auto;
  scrollbar-width: thin;
}

.modal.show {
  transform: translateY(0) scale(1);
  opacity: 1;
}

.modal.wide {
  width: min(94vw, 760px);
}

.modal-pad {
  padding: clamp(20px, 4vw, 30px);
}

.modal-close {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 2;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: rgba(0, 0, 0, 0.06);
  color: #5b6b86;
  font-size: 18px;
}

.modal-close:hover {
  background: rgba(0, 0, 0, 0.1);
}

.modal h2 {
  font-family: 'Fredoka', sans-serif;
  font-size: clamp(24px, 3vw, 32px);
  margin: 0 0 6px;
  color: var(--ink);
  line-height: 1.1;
}

.modal .modal-sub {
  font-size: 13px;
  line-height: 1.5;
  color: var(--ink-soft);
  margin: 0 0 18px;
}

.modal-actions {
  display: flex;
  flex-direction: column;
  gap: 9px;
  margin-top: 20px;
}

.modal-actions .row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 9px;
}

.modal-actions .btn {
  width: 100%;
}

/* Deed card */
.deed {
  border-radius: 26px;
  overflow: hidden;
  background: var(--paper);
}

.deed-head {
  padding: 22px 26px 18px;
  color: #fff;
  position: relative;
  overflow: hidden;
}

.deed-head::after {
  content: '';
  position: absolute;
  right: -30px;
  top: -50px;
  width: 150px;
  height: 150px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.14);
}

.deed-head .kicker {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  opacity: 0.8;
  margin-bottom: 6px;
}

.deed-head h2 {
  color: #fff;
  margin: 0;
  font-size: 30px;
}

.deed-head .price {
  position: absolute;
  right: 24px;
  bottom: 18px;
  font-family: 'Fredoka', sans-serif;
  font-weight: 700;
  font-size: 28px;
  text-shadow: 0 2px 0 rgba(0, 0, 0, 0.12);
}

.deed-body {
  padding: 20px 26px 24px;
}

.deed-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 7px 0;
  border-bottom: 1px dashed #e7ddca;
  font-size: 13px;
  color: #5b6b86;
}

.deed-row:last-child {
  border-bottom: 0;
}

.deed-row b {
  color: var(--ink);
  font-size: 14px;
}

.deed-row .rent {
  color: #1f7a5c;
  font-weight: 800;
}

.deed-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 5px 9px;
  border-radius: 999px;
  background: #fff2cf;
  color: #8a5a00;
  margin-bottom: 12px;
}

.deed-badge.owned {
  background: #e4f7ef;
  color: #146b52;
}

.deed-note {
  margin-top: 14px;
  font-size: 12px;
  line-height: 1.5;
  color: #8a7a63;
  background: #f8f2e5;
  border-radius: 12px;
  padding: 10px 12px;
}

/* Event card */
.event-card {
  text-align: center;
  padding: clamp(22px, 4vw, 32px);
  background:
    radial-gradient(80% 60% at 50% 0%, #fff7e0, transparent 70%),
    var(--paper);
}

.event-icon {
  width: 92px;
  height: 92px;
  margin: 4px auto 14px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: #fff3d1;
  box-shadow: inset 0 -6px 0 rgba(160, 110, 20, 0.12);
}

.event-icon img {
  width: 54px;
  height: 54px;
}

.event-card .kicker {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: #b0821d;
  margin-bottom: 6px;
}

.event-card h2 {
  margin-bottom: 8px;
}

.event-text {
  font-size: 14px;
  line-height: 1.6;
  color: #5b6b86;
  margin: 0 auto 16px;
  max-width: 340px;
}

.effect-pills {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  justify-content: center;
  margin-bottom: 4px;
}

.effect-pill {
  font-size: 11px;
  font-weight: 800;
  padding: 6px 10px;
  border-radius: 999px;
  background: #eef4ff;
  color: #315a9a;
}
.effect-pill.good {
  background: #e4f7ef;
  color: #146b52;
}
.effect-pill.bad {
  background: #ffe8e4;
  color: #a63a2c;
}
.effect-pill.joy {
  background: #ffe8ef;
  color: #a63a64;
}

/* Choice card */
.choice-card {
  padding: clamp(20px, 4vw, 28px);
}

.choice-head {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 6px;
}

.choice-icon {
  width: 48px;
  height: 48px;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: #fff1c9;
  flex: 0 0 auto;
}

.choice-icon img {
  width: 28px;
  height: 28px;
}

.choice-options {
  display: flex;
  flex-direction: column;
  gap: 9px;
  margin-top: 18px;
}

.choice-option {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  text-align: left;
  padding: 13px 14px;
  border-radius: 15px;
  background: #f8f3e8;
  border: 2px solid transparent;
  transition: border-color 0.15s ease, background 0.15s ease, transform 0.15s ease;
}

.choice-option:hover {
  background: #fff8e9;
  border-color: #ffd166;
  transform: translateY(-1px);
}

.choice-option:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  transform: none;
}

.choice-option .opt-icon {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  background: #fffdf7;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  font-family: 'Fredoka', sans-serif;
  font-weight: 700;
  color: #b0821d;
}

.choice-option .opt-main {
  flex: 1;
  min-width: 0;
}

.choice-option .opt-label {
  display: block;
  font-family: 'Fredoka', sans-serif;
  font-weight: 600;
  font-size: 15px;
  color: var(--ink);
}

.choice-option .opt-detail {
  display: block;
  font-size: 11px;
  color: #8a7a63;
  margin-top: 2px;
}

.choice-option .opt-arrow {
  color: #b9a888;
  font-size: 18px;
}

.choice-option.cant-afford .opt-detail {
  color: #c04f40;
}

/* Rules */
.rules-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
  margin-top: 18px;
}

.rule {
  display: flex;
  gap: 12px;
}

.rule-icon {
  width: 40px;
  height: 40px;
  flex: 0 0 auto;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: #fff1c9;
}

.rule-icon img {
  width: 24px;
  height: 24px;
}

.rule strong {
  display: block;
  font-family: 'Fredoka', sans-serif;
  font-size: 15px;
  color: var(--ink);
  margin-bottom: 2px;
}

.rule p {
  margin: 0;
  font-size: 12px;
  line-height: 1.5;
  color: #5b6b86;
}

/* Results */
.results {
  padding: clamp(20px, 4vw, 30px);
}

.results-head {
  text-align: center;
  margin-bottom: 18px;
}

.results-head .crown {
  font-size: 40px;
  line-height: 1;
  margin-bottom: 4px;
  filter: drop-shadow(0 6px 12px rgba(180, 120, 0, 0.3));
}

.results-head h2 {
  font-size: clamp(26px, 4vw, 36px);
  margin: 0;
}

.results-head p {
  font-size: 13px;
  color: #8a7a63;
  margin: 6px 0 0;
}

.ranking {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.rank-row {
  display: grid;
  grid-template-columns: 30px 40px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 15px;
  background: #f8f3e8;
  border: 1px solid transparent;
}

.rank-row.winner {
  background: #fff4d2;
  border-color: #ffd166;
}

.rank-row .rank {
  font-family: 'Fredoka', sans-serif;
  font-weight: 700;
  font-size: 17px;
  color: #b0821d;
  text-align: center;
}

.rank-row .avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: #fff;
  font-family: 'Fredoka', sans-serif;
  font-weight: 700;
  font-size: 14px;
  background: var(--player-color);
  box-shadow: inset 0 -3px 0 rgba(0, 0, 0, 0.15);
}

.rank-row .r-name {
  font-family: 'Fredoka', sans-serif;
  font-weight: 600;
  font-size: 15px;
  color: var(--ink);
  line-height: 1.1;
}

.rank-row .r-detail {
  font-size: 10px;
  color: #8a7a63;
  margin-top: 2px;
}

.rank-row .r-score {
  font-family: 'Fredoka', sans-serif;
  font-weight: 700;
  font-size: 20px;
  color: #1f7a5c;
  text-align: right;
}

.breakdown {
  margin-top: 16px;
  border-top: 1px dashed #e7ddca;
  padding-top: 14px;
}

.breakdown h3 {
  font-family: 'Fredoka', sans-serif;
  font-size: 14px;
  margin: 0 0 10px;
  color: var(--ink);
}

.breakdown-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px 18px;
}

.breakdown-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 11px;
  color: #8a7a63;
  padding: 4px 0;
  border-bottom: 1px dotted #eee3d1;
}

.breakdown-row b {
  color: var(--ink);
  font-size: 12px;
}

.breakdown-row.total {
  grid-column: 1 / -1;
  border-bottom: 0;
  padding-top: 8px;
  font-size: 13px;
  color: var(--ink);
}

.breakdown-row.total b {
  font-family: 'Fredoka', sans-serif;
  font-size: 20px;
  color: #1f7a5c;
}

.results-actions {
  display: flex;
  gap: 9px;
  margin-top: 20px;
}

.results-actions .btn {
  flex: 1;
}

/* Pause / menu */
.pause-card {
  padding: clamp(22px, 4vw, 30px);
}

.pause-card .logo-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 20px;
}

.pause-card .logo-row .brand-mark {
  width: 44px;
  height: 44px;
  border-radius: 13px;
}

.pause-card .logo-row h2 {
  margin: 0;
}

.pause-actions {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.pause-meta {
  margin-top: 16px;
  padding-top: 14px;
  border-top: 1px dashed #e7ddca;
  font-size: 11px;
  color: #8a7a63;
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

/* Inspect */
.inspect-card {
  padding: 0;
}

.inspect-body {
  padding: 20px 24px 24px;
}

/* Confetti */
#confetti {
  position: absolute;
  inset: 0;
  z-index: 45;
  pointer-events: none;
  overflow: hidden;
}

.confetti-piece {
  position: absolute;
  width: 8px;
  height: 14px;
  border-radius: 2px;
  top: -20px;
  animation: confetti-fall linear forwards;
}

@keyframes confetti-fall {
  to {
    transform: translateY(110vh) rotate(720deg);
  }
}

/* ------------------------------------------------------------------ */
/* Splash                                                              */
/* ------------------------------------------------------------------ */

#splash {
  position: absolute;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  background: radial-gradient(90% 80% at 50% 30%, #243a60, #0b1426);
  transition: opacity 0.55s ease, visibility 0.55s ease;
}

#splash.done {
  opacity: 0;
  visibility: hidden;
}

.splash-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  color: var(--cream);
}

.splash-logo {
  width: 92px;
  height: 92px;
  border-radius: 26px;
  background: linear-gradient(145deg, #ffd166, #ff9f43);
  display: grid;
  place-items: center;
  font-family: 'Fredoka', sans-serif;
  font-weight: 700;
  font-size: 46px;
  color: #4a2c00;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.4);
  animation: splash-pop 0.8s cubic-bezier(0.2, 1.5, 0.4, 1) both;
}

@keyframes splash-pop {
  from {
    transform: scale(0.7) rotate(-8deg);
    opacity: 0;
  }
}

.splash-inner h1 {
  font-family: 'Fredoka', sans-serif;
  font-size: 26px;
  letter-spacing: 0.02em;
  margin: 0;
}

.splash-inner p {
  font-size: 10px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: rgba(255, 248, 234, 0.5);
  margin: 0;
}

.splash-bar {
  width: 120px;
  height: 3px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.15);
  overflow: hidden;
}

.splash-bar i {
  display: block;
  height: 100%;
  width: 40%;
  background: var(--gold);
  border-radius: 3px;
  animation: splash-load 1s ease-in-out infinite;
}

@keyframes splash-load {
  0% {
    transform: translateX(-100%);
  }
  100% {
    transform: translateX(350%);
  }
}

/* ------------------------------------------------------------------ */
/* Responsive                                                          */
/* ------------------------------------------------------------------ */

@media (max-width: 1080px) {
  .hud-main {
    grid-template-columns: 230px minmax(0, 1fr);
  }
  .side-panel {
    display: none;
  }
}

@media (max-width: 820px) {
  #start-screen {
    background: linear-gradient(to top, rgba(16, 27, 51, 0.82) 0%, rgba(16, 27, 51, 0.25) 48%, transparent 70%);
    padding: calc(14px + var(--safe-top)) 16px calc(14px + var(--safe-bottom));
    justify-content: flex-start;
    gap: 12px;
  }
  .start-top {
    flex-shrink: 0;
  }
  .brand-mark {
    width: 38px;
    height: 38px;
    font-size: 21px;
    border-radius: 11px;
  }
  .brand-text strong {
    font-size: 14px;
  }
  .brand-text span {
    font-size: 8px;
  }
  .start-main {
    grid-template-columns: 1fr;
    align-items: end;
    gap: 14px;
    flex: 1;
    min-height: 0;
    align-content: end;
  }
  .hero {
    padding-bottom: 0;
  }
  .hero-kicker {
    margin-bottom: 8px;
    font-size: 9px;
  }
  .hero h1 {
    font-size: clamp(42px, 13vw, 64px);
    margin-bottom: 10px;
  }
  .hero h1 .outline {
    font-size: 0.58em;
  }
  .hero p {
    font-size: 13px;
    max-width: 340px;
  }
  .hero-badges {
    display: none;
  }
  .setup-card {
    max-width: none;
    width: 100%;
    justify-self: stretch;
    padding: 16px;
    border-radius: 22px;
  }
  .setup-card h2 {
    font-size: 21px;
  }
  .setup-card .sub {
    font-size: 11px;
    margin-bottom: 12px;
  }
  .field {
    margin-bottom: 10px;
  }
  .field-label {
    font-size: 9px;
    margin-bottom: 5px;
  }
  .segmented button {
    padding: 8px 4px;
    font-size: 11px;
  }
  .setup-actions {
    margin-top: 14px;
    gap: 7px;
  }
  .setup-actions .btn {
    padding: 11px 14px;
    font-size: 15px;
  }
  .start-footer {
    display: none;
  }

  #hud {
    padding: calc(8px + var(--safe-top)) 8px calc(8px + var(--safe-bottom));
  }
  .hud-brand .brand-text {
    display: none;
  }
  .hud-brand .brand-mark {
    width: 32px;
    height: 32px;
    font-size: 18px;
    border-radius: 9px;
  }
  .chapter-pill {
    font-size: 9px;
    padding: 6px 10px;
    margin-top: 1px;
  }
  .hud-actions {
    gap: 6px;
  }
  .icon-btn {
    width: 36px;
    height: 36px;
    border-radius: 11px;
  }
  .icon-btn svg {
    width: 17px;
    height: 17px;
  }
  .hud-main {
    display: block;
    padding-top: 8px;
  }
  .players-panel {
    display: none;
  }
  .mobile-players {
    display: flex;
    gap: 6px;
    overflow-x: auto;
    padding-bottom: 4px;
    pointer-events: auto;
    scrollbar-width: none;
  }
  .mobile-players::-webkit-scrollbar {
    display: none;
  }
  .m-player {
    flex: 0 0 auto;
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 5px 9px 5px 5px;
    border-radius: 999px;
    background: rgba(255, 250, 240, 0.88);
    border: 1px solid rgba(255, 255, 255, 0.55);
    box-shadow: 0 6px 16px rgba(16, 27, 51, 0.12);
    backdrop-filter: blur(10px);
  }
  .m-player.active {
    box-shadow: 0 0 0 2px var(--player-color), 0 6px 16px rgba(16, 27, 51, 0.18);
  }
  .m-player .m-avatar {
    width: 26px;
    height: 26px;
    border-radius: 50%;
    display: grid;
    place-items: center;
    color: #fff;
    font-family: 'Fredoka', sans-serif;
    font-weight: 700;
    font-size: 11px;
    background: var(--player-color);
  }
  .m-player .m-info {
    display: flex;
    flex-direction: column;
    line-height: 1.05;
  }
  .m-player .m-name {
    font-size: 9px;
    font-weight: 800;
    color: var(--ink);
    max-width: 68px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .m-player .m-cash {
    font-size: 9px;
    font-weight: 800;
    color: #1f7a5c;
  }
  .m-player.retired {
    opacity: 0.55;
  }
  .center-column {
    display: none;
  }
  .hud-bottom {
    gap: 5px;
  }
  .dock {
    width: 100%;
    max-width: 460px;
    padding: 7px;
    gap: 7px;
    border-radius: 19px;
  }
  .dock .die-preview {
    width: 44px;
    height: 44px;
    border-radius: 12px;
  }
  .dock .die-preview svg {
    width: 28px;
    height: 28px;
  }
  .dock .roll-btn {
    min-width: 0;
    flex: 1;
    height: 46px;
    font-size: 16px;
    border-radius: 13px;
  }
  .dock .end-btn {
    min-width: 0;
    flex: 1;
    height: 46px;
    font-size: 15px;
    border-radius: 13px;
  }
  .dock .hint {
    display: none;
  }
  .log-panel {
    display: none;
  }
  #toasts {
    top: calc(96px + var(--safe-top));
    width: 94vw;
  }
  .toast {
    font-size: 11px;
    padding: 8px 12px;
